"""
    Display a traingle shape made of x with a certain height

    Args:
        height ([int]): The desired height for the shape

    Returns:
        [str]: A triangle shape made of x
    """
def triangle_shape(height: Any) -> object {
    triangle = "";
    nbEspaces = height - 1;
    for indice in range(height) {
        triangle += nbEspaces * " ";
        triangle += "x" * ((indice * 2) + 1);
        triangle += nbEspaces * " ";
        if (indice < (height - 1)) {
            triangle += "\n";
        }
        nbEspaces += -1;
    }
    return triangle;
}

test_blocks:
test "t0" {
    assert (triangle_shape(0) == "");;
}

test "t1" {
    assert (triangle_shape(4) == "   x   \n  xxx  \n xxxxx \nxxxxxxx");;
}

test "t2" {
    assert (
        triangle_shape(5) == "    x    \n   xxx   \n  xxxxx  \n xxxxxxx \nxxxxxxxxx"
    );;
}

test "t3" {
    assert (triangle_shape(1) == "x");;
}

test "t4" {
    assert (triangle_shape(3) == "  x  \n xxx \nxxxxx");;
}

test "t5" {
    assert (triangle_shape(1) == 'x');;
}

test "t6" {
    assert (triangle_shape(0) == '');;
}

test "t7" {
    assert (triangle_shape(2) == " x \nxxx");;
}
